const fs = require('fs');
const ExcelJS = require('exceljs');

async function checkExcel() {
  const inputLines = fs.readFileSync('C:/Users/lg/.gemini/antigravity/brain/f2533ba2-96b2-426b-85af-73e28ca73587/scratch/input_batch.tsv', 'utf-8')
    .split('\n')
    .filter(l => l.trim().length > 0);
  const inputBiznos = new Set();
  inputLines.forEach(l => {
    const parts = l.split('\t');
    if (parts[3]) inputBiznos.add(parts[3].trim());
  });

  const dataFiles = fs.readdirSync('data').filter(f => f.endsWith('.xlsx'));
  for (const f of dataFiles) {
    console.log('Checking', f);
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.readFile('data/' + f);
    let matchCount = 0;
    wb.eachSheet(sheet => {
      sheet.eachRow(row => {
        const rowVals = row.values.map(v => String(v || '').trim());
        inputBiznos.forEach(b => {
          if (rowVals.includes(b)) matchCount++;
        });
      });
    });
    console.log(f, 'total matches:', matchCount);
  }
}
checkExcel();
